// Cleanify Modern Splash Screen
(function CleanifySplash() {
    const styles = `
        @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@300;400;700&display=swap');

        #cleanify-loader {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background-color: #090909;
            z-index: 999999;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            font-family: 'Montserrat', sans-serif;
            transition: opacity 1.5s cubic-bezier(0.25, 1, 0.5, 1), visibility 1.5s;
            overflow: hidden;
        }

        .loader-content {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            flex-grow: 1;
        }

        .spotify-logo-wrapper {
            position: relative;
            width: 100px;
            height: 100px;
            margin-bottom: 24px;
            animation: pulseGlow 3s ease-in-out infinite alternate;
        }

        .spotify-logo-wrapper svg {
            width: 100%;
            height: 100%;
            fill: #1DB954;
            filter: drop-shadow(0 0 15px rgba(29, 185, 84, 0.6));
        }

        .cleanify-title {
            color: #ffffff;
            font-size: 2.5rem;
            font-weight: 700;
            letter-spacing: 4px;
            text-transform: uppercase;
            background: linear-gradient(120deg, #ffffff 0%, #a8a8a8 50%, #ffffff 100%);
            background-size: 200% auto;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            animation: shineText 4s linear infinite, fadeInUp 1s ease-out;
        }

        .cleanify-footer {
            margin-bottom: 40px;
            font-size: 0.85rem;
            font-weight: 300;
            color: rgba(255, 255, 255, 0.25);
            letter-spacing: 2px;
            animation: fadeIn 2s ease-in;
        }

        .loader-hidden {
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
        }

        @keyframes pulseGlow {
            0% {
                transform: scale(0.98);
                filter: drop-shadow(0 0 10px rgba(29, 185, 84, 0.4));
            }
            100% {
                transform: scale(1.02);
                filter: drop-shadow(0 0 30px rgba(29, 185, 84, 0.8));
            }
        }

        @keyframes shineText {
            to { background-position: 200% center; }
        }

        @keyframes fadeInUp {
            from {
                opacity: 0;
                transform: translateY(20px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes fadeIn {
            from { opacity: 0; }
            to { opacity: 0.25; }
        }
    `;

    const styleSheet = document.createElement("style");
    styleSheet.innerText = styles;
    document.head.appendChild(styleSheet);

    const loader = document.createElement("div");
    loader.id = "cleanify-loader";

    loader.innerHTML = `
        <div class="loader-content">
            <div class="spotify-logo-wrapper">
                <img src="https://raw.githubusercontent.com/Takayashii/Cleanify/main/cleanify-icon.png" alt="Cleanify" style="width:100%;height:100%;object-fit:contain;border-radius:20px;">
            </div>
            <div class="cleanify-title">Cleanify</div>
        </div>
        <div class="cleanify-footer">Made by Takayashii</div>
    `;

    document.body.appendChild(loader);

    function hideLoader() {
        loader.classList.add("loader-hidden");
        setTimeout(() => {
            loader.remove();
        }, 1500);
    }

    const checkLoaded = setInterval(() => {
        const mainApp = document.querySelector("#main") || document.querySelector(".Root__top-container");
        
        if (mainApp && Spicetify.Platform) {
            clearInterval(checkLoaded);
            setTimeout(hideLoader, 3000);
        }
    }, 100);
})();

/* Cleanify: safe container/control poster (probes once; disables if resolver missing) */
var containerControlPost = (function() {
    var fails = 0;
    return function(payload) {
        if (fails >= 3) return Promise.resolve();
        try {
            if (!Spicetify || !Spicetify.CosmosAsync) return Promise.resolve();
        } catch (e) { return Promise.resolve(); }
        try {
            var p = Spicetify.CosmosAsync.post("sp://messages/v1/container/control", payload);
            return Promise.resolve(p).then(
                function(v) { fails = 0; return v; },
                function() {
                    fails += 1;
                    if (fails === 3) console.debug("[Cleanify] container/control resolver unavailable; disabling titlebar messages");
                    return undefined;
                }
            );
        } catch (e) { return Promise.resolve(); }
    };
})();

/* ==========================================
   CONTROLS
   ========================================== */
{
  (async function noControls() {
      if (!Spicetify.CosmosAsync || !Spicetify.Platform.UpdateAPI || !Spicetify.Platform.ControlMessageAPI) {
          setTimeout(noControls, 10);
          return;
      }

      // Override some theming of the html element
      const style = document.createElement("style");
      style.innerHTML = `
          html > body::after { display: none !important; }
          .Root__globalNav { padding-inline: 8px !important; }
          .Titlebar { display: none !important; }
      `;
      document.head.appendChild(style);

      // Function to check and apply the titlebar
      const checkAndApplyTitlebar = API => {
          if (API) {
              if (API._updateUiClient?.updateTitlebarHeight) {
                  API._updateUiClient.updateTitlebarHeight({ height: 1 });
              }

              if (API._updateUiClient?.setButtonsVisibility) {
                  API._updateUiClient.setButtonsVisibility(false);
              }

              window.addEventListener("beforeunload", () => {
                  if (API._updateUiClient?.setButtonsVisibility) {
                      API._updateUiClient.setButtonsVisibility({ showButtons: true });
                  }
              });
          }

          containerControlPost({ type: "update_titlebar", height: "1px" });
      };

      // Apply titlebar initially
      checkAndApplyTitlebar(Spicetify.Platform.ControlMessageAPI); // Spotify >= 1.2.53
      checkAndApplyTitlebar(Spicetify.Platform.UpdateAPI); // Spotify >= 1.2.51

      // Ensure the titlebar is hidden (spotify likes to change it back sometimes on loadup)
      async function enforceHeight() {
          checkAndApplyTitlebar(Spicetify.Platform.ControlMessageAPI);
          checkAndApplyTitlebar(Spicetify.Platform.UpdateAPI);
      }

      let intervalId = setInterval(enforceHeight, 100); // Every 100ms
      setTimeout(() => {
          clearInterval(intervalId); // Stop after 10 seconds
      }, 10000);

      // Detect fullscreen changes and apply titlebar hiding
      const handleFullscreenChange = () => {
          checkAndApplyTitlebar(Spicetify.Platform.ControlMessageAPI);
          checkAndApplyTitlebar(Spicetify.Platform.UpdateAPI);
          clearInterval(intervalId);
          intervalId = setInterval(enforceHeight, 100);
          setTimeout(() => clearInterval(intervalId), 10000);
      };

      // Add in event listening for F8 pressed to re enable
      let titlebarEnabled = false;
      document.addEventListener("keydown", (event) => {
          if (event.key !== "F8") return;
          titlebarEnabled = !titlebarEnabled;
          if (titlebarEnabled) {
              clearInterval(intervalId);
              containerControlPost({ type: "update_titlebar", height: "30px" });
          } else {
              checkAndApplyTitlebar(Spicetify.Platform.ControlMessageAPI);
              checkAndApplyTitlebar(Spicetify.Platform.UpdateAPI);
              intervalId = setInterval(() => {
                  checkAndApplyTitlebar(Spicetify.Platform.ControlMessageAPI);
                  checkAndApplyTitlebar(Spicetify.Platform.UpdateAPI);
              }, 100);
              setTimeout(() => clearInterval(intervalId), 10000);
          }
      });

      // Add event listener for fullscreen change
      document.addEventListener("fullscreenchange", handleFullscreenChange);
      document.addEventListener("webkitfullscreenchange", handleFullscreenChange);
      document.addEventListener("mozfullscreenchange", handleFullscreenChange);
      document.addEventListener("msfullscreenchange", handleFullscreenChange);

      // Spotify fullscreen does NOT fire fullscreenchange on Escape — detect it via keydown
      document.addEventListener("keydown", (event) => {
          if (event.key === "Escape") {
              setTimeout(handleFullscreenChange, 50);
              setTimeout(handleFullscreenChange, 200);
              setTimeout(handleFullscreenChange, 500);
              setTimeout(handleFullscreenChange, 1000);
          }
      });
  })();
}

(function CustomHomeModule() {
    async function injectCustomHome() {
        const mainContainer = document.querySelector('section[data-testid="home-page"]');
        if (!mainContainer || document.getElementById('custom-home-injected')) return;

        const customUI = document.createElement('div');
        customUI.id = 'custom-home-injected';
        customUI.className = 'custom-home-container';
        
        customUI.innerHTML = `
            <div class="custom-home-row">
                <div class="custom-home-col">
                    <h1 class="custom-home-title">Your Playlists</h1>
                    <div class="playlist-folder-wrapper">
                        <div class="folder-item">
                            <div class="folder-icon"></div>
                        </div>
                        <div class="playlist-list-horizontal" id="horizontal-playlists"></div>
                    </div>
                </div>
                <div class="custom-home-col custom-home-col--right">
                    <h1 class="custom-home-title">Liked Songs</h1>
                    <div class="playlist-folder-wrapper playlist-folder-wrapper--right">
                        <div class="folder-item">
                            <div class="folder-icon liked-songs-folder-icon">
                                <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>
                            </div>
                        </div>
                        <div class="playlist-list-horizontal" id="horizontal-liked-songs"></div>
                    </div>
                </div>
            </div>
        `;

        mainContainer.prepend(customUI);

        const folderTiles = customUI.querySelectorAll('.custom-home-col .folder-item');
        if (folderTiles[0]) {
            folderTiles[0].onclick = (e) => {
                e.stopPropagation();
                openAllPlaylistsMenu();
            };
        }
        if (folderTiles[1]) {
            folderTiles[1].onclick = (e) => {
                e.stopPropagation();
                openLikedSongs();
            };
        }

        loadPlaylists();
        loadLikedSongs();
    }

    async function loadPlaylists() {

        const playlists = await Spicetify.Platform.RootlistAPI.getContents();
        const listContainer = document.getElementById('horizontal-playlists');
        
        const limit = 3;
        const items = playlists.items || [];

        items.slice(0, limit).forEach(item => {
            const card = document.createElement('div');
            card.className = 'playlist-card';
            card.onclick = (e) => {
                e.stopPropagation();
                window.location.href = `spotify:playlist:${item.uri.split(':').pop()}`;
            };

            const hasImage = item.images && item.images.length > 0 && item.images[0].url;
            const imageHtml = hasImage 
                ? `<img src="${item.images[0].url}" class="playlist-card-img" loading="lazy" decoding="async">`
                : `<div class="playlist-card-placeholder"><svg width="32" height="32" viewBox="0 0 24 24" fill="currentColor"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg></div>`;

            card.innerHTML = `
                ${imageHtml}
                <span class="playlist-card-name">${item.name}</span>
            `;
            listContainer.appendChild(card);
        });

        if (items.length > limit) {
            const moreCard = document.createElement('div');
            moreCard.className = 'playlist-card';
            moreCard.innerHTML = `
                <div style="font-size:30px; pointer-events:none; margin-bottom: 5px;">...</div>
                <span style="pointer-events:none; font-weight: bold;">And More...</span>
            `;
            
            moreCard.onclick = (e) => {
                e.stopPropagation();
                openAllPlaylistsMenu();
            };
            listContainer.appendChild(moreCard);
        }
    }

    async function getAllPlaylists() {
        const result = [];
        const walk = (items) => {
            (items || []).forEach(item => {
                if (item.subitems) {
                    walk(item.subitems);
                } else if (item.uri && item.name) {
                    result.push({
                        name: item.name,
                        uri: item.uri,
                        image: item.images?.[0]?.url || item.image?.url || ""
                    });
                }
            });
        };
        try {
            const contents = await Spicetify.Platform.RootlistAPI.getContents();
            walk(contents.items);
        } catch (e) {}
        return result;
    }

    function openAllPlaylistsMenu() {
        const overlay = document.createElement('div');
        overlay.className = 'playlists-menu-overlay';
        overlay.innerHTML = `
            <div class="playlists-menu" role="dialog" aria-modal="true">
                <div class="playlists-menu-header">
                    <h2>All Playlists</h2>
                    <button type="button" class="playlists-menu-close" aria-label="Close">✕</button>
                </div>
                <div class="playlists-menu-list">
                    <div class="playlists-menu-message">Loading...</div>
                </div>
            </div>
        `;
        document.body.appendChild(overlay);

        const close = () => overlay.remove();
        const onKey = (e) => { if (e.key === 'Escape') close(); };
        overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
        overlay.querySelector('.playlists-menu-close').addEventListener('click', close);
        document.addEventListener('keydown', onKey);

        const listEl = overlay.querySelector('.playlists-menu-list');

        (async () => {
            const playlists = await getAllPlaylists();
            if (!overlay.isConnected) return;
            if (!playlists.length) {
                listEl.innerHTML = '<div class="playlists-menu-message">No playlists found.</div>';
                return;
            }
            listEl.innerHTML = '';
            playlists.forEach(p => {
                const row = document.createElement('div');
                row.className = 'playlists-menu-item';
                row.innerHTML = `
                    ${p.image ? `<img src="${p.image}" alt="" loading="lazy" decoding="async">` : '<div class="playlists-menu-noimg"></div>'}
                    <span class="playlists-menu-name">${p.name}</span>
                `;
                row.onclick = () => {
                    close();
                    window.location.href = p.uri;
                };
                listEl.appendChild(row);
            });
        })();
    }

    function likedSongsCard(track, onClick) {
        const card = document.createElement('div');
        card.className = 'playlist-card';
        card.onclick = (e) => {
            e.stopPropagation();
            onClick();
        };

        const imageHtml = track.image
            ? `<img src="${track.image}" class="playlist-card-img" loading="lazy" decoding="async">`
            : `<div class="playlist-card-placeholder"><svg width="32" height="32" viewBox="0 0 24 24" fill="currentColor"><path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg></div>`;

        card.innerHTML = `${imageHtml}<span class="playlist-card-name">${track.name}</span>`;
        return card;
    }

    function normalizeLikedItem(item) {
        const t = item.track || item;
        return {
            name: t?.name || "Unknown",
            uri: t?.uri || "",
            image: t?.album?.images?.[0]?.url || ""
        };
    }

    async function loadLikedSongs() {
        const listContainer = document.getElementById('horizontal-liked-songs');
        if (!listContainer) return;

        const limit = 3;
        const limitPlus = limit + 1;
        let tracks = [];
        let hasMore = false;

        try {
            const lib = Spicetify?.Platform?.LibraryAPI;
            if (lib) {
                const res = lib.getLikedTracks
                    ? await lib.getLikedTracks({ limit: limitPlus, offset: 0 })
                    : lib.getTracks
                        ? await lib.getTracks({ limit: limitPlus, offset: 0 })
                        : null;
                if (res) {
                    tracks = (res.items || []).map(normalizeLikedItem);
                    hasMore = tracks.length > limit || (typeof res.total === "number" && res.total > limit);
                }
            }
        } catch (e) {}

        if (!tracks.length) {
            try {
                const res = await Spicetify.CosmosAsync.get("sp://core-playlist/v1/collection/tracks");
                const items = res.items || [];
                tracks = items.map(normalizeLikedItem);
                hasMore = tracks.length > limit;
            } catch (e) {
                return;
            }
        }

        tracks.slice(0, limit).forEach(track => {
            listContainer.appendChild(likedSongsCard(track, () => {
                if (track.uri) window.location.href = track.uri;
            }));
        });

        if (hasMore) {
            const moreCard = document.createElement('div');
            moreCard.className = 'playlist-card';
            moreCard.innerHTML = `
                <div style="font-size:30px; pointer-events:none; margin-bottom: 5px;">...</div>
                <span style="pointer-events:none; font-weight: bold;">And More...</span>
            `;
            moreCard.onclick = (e) => {
                e.stopPropagation();
                openLikedSongs();
            };
            listContainer.appendChild(moreCard);
        }
    }

    function openLikedSongs() {
        const link = document.querySelector(
            'a[href="spotify:collection:tracks"], a[href*="collection/tracks"], [data-testid="liked-songs"]'
        );
        if (link) {
            link.click();
            return;
        }
        const H = Spicetify?.Platform?.History;
        if (H?.push) {
            H.push('spotify:collection:tracks');
            return;
        }
        window.location.href = 'spotify:collection:tracks';
    }


    setInterval(injectCustomHome, 1000); 
})();

(async function FinalStats() {
    if (!window.Dexie) {
        const s = document.createElement('script');
        s.src = 'https://unpkg.com/dexie/dist/dexie.js';
        document.head.appendChild(s);
        await new Promise(r => s.onload = r);
    }
    const db = new Dexie("MyStatsDB");
    db.version(2).stores({ history: "++id, artist, track, image, uri, album" });

    const WRAPPER_ID = "stats-wrapper";
    let lastTrackUri = null;
    let lastProgress = 0;

    function mount() {
        const home = document.querySelector('section[data-testid="home-page"]');
        if (!home || document.getElementById(WRAPPER_ID)) return;
        
        const wrapper = document.createElement('div');
        wrapper.id = WRAPPER_ID;
        wrapper.innerHTML = `
            <div class="stats-outer-header"><h1>Top Heavy Rotation</h1></div>
            <div class="sp-plus-stats-container">
                <div class="sp-plus-panel"><h2 class="sp-plus-header">Top Artists</h2><div class="sp-artists-grid" id="artists-grid"></div></div>
                <div class="sp-plus-panel"><h2 class="sp-plus-header">Top Tracks</h2><div class="sp-tracks-list" id="tracks-list"></div></div>
            </div>
        `;
        home.appendChild(wrapper);
        render(); 
    }

    async function render() {
        if (!document.getElementById(WRAPPER_ID)) return;

        const data = await db.history.toArray();
        if (!data.length) return;

        const total = data.length;
        const art = {}, trk = {}, img = {}, artUri = {}, trackUri = {}, alb = {};

        for (const d of data) {
            art[d.artist] = (art[d.artist] || 0) + 1;
            trk[d.track] = (trk[d.track] || 0) + 1;
            if (d.image && !img[d.track]) img[d.track] = d.image;
            if (d.uri?.includes("artist")) artUri[d.artist] = d.uri;
            if (d.uri?.includes("track")) trackUri[d.track] = d.uri;
            if (d.album) alb[d.track] = d.album;
        }

        const topA = Object.entries(art).sort((a,b)=>b[1]-a[1]).slice(0,5);
        const topT = Object.entries(trk).sort((a,b)=>b[1]-a[1]).slice(0,5);

        const grid = document.getElementById('artists-grid');
        const list = document.getElementById('tracks-list');
        if (!grid || !list) return;

        grid.innerHTML = topA.map(([name, count]) => `
            <div class="sp-artist-col">
                <div class="sp-bar-v"><div class="sp-bar-fill animate-bar" style="height:0px;" data-h="${(count/total)*220}"></div></div>
                <div class="sp-artist-perc">${Math.round((count/total)*100)}%</div>
                <div class="sp-artist-name clickable" data-uri="${artUri[name] || ''}">${name}</div>
            </div>
        `).join('');

        list.innerHTML = topT.map(([name, count], i) => `
            <div class="sp-track-row">
                <div class="sp-track-left clickable" data-uri="${trackUri[name] || ''}">
                    <span style="color:#aaa; font-size:12px; min-width:20px;">${i + 1}.</span>
                    <div class="sp-track-cover">${img[name] ? `<img src="${img[name]}">` : ''}</div>
                    <span class="sp-track-name">${name} <small style="display:block; opacity:0.6; font-size:10px;">${alb[name] || ''}</small></span>
                </div>
                <div class="sp-bar-h"><div class="sp-bar-fill-h animate-bar" style="width:0px;" data-w="${(count/total)*200}"></div></div>
            </div>
        `).join('');

        requestAnimationFrame(() => {
            document.querySelectorAll('.animate-bar').forEach(el => {
                if (el.dataset.h) el.style.height = el.dataset.h + 'px';
                if (el.dataset.w) el.style.width = el.dataset.w + 'px';
            });
        });

        document.querySelectorAll('.clickable').forEach(el => {
            el.onclick = (e) => {
                e.stopPropagation();
                const uri = el.getAttribute('data-uri');
                if (uri) Spicetify.Platform.History.push(uri);
            };
        });
    }

    async function logCurrentTrack(item) {
        if (!item) return;
        await db.history.add({
            artist: item.artists?.[0].name,
            track: item.name,
            uri: item.uri,
            image: item.album?.images?.[0]?.url,
            album: item.album?.name || "Unknown"
        });
        if(item.artists?.[0]) {
            await db.history.where('artist').equals(item.artists[0].name).modify({uri: item.artists[0].uri});
        }
        render();
    }

    const observer = new MutationObserver(() => {
        mount();
    });
    observer.observe(document.body, { childList: true, subtree: true });

    Spicetify.Player.addEventListener("songchange", async () => {
        const item = Spicetify.Player.data.item;
        if (!item) return;
        lastTrackUri = item.uri;
        await logCurrentTrack(item);
    });

    Spicetify.Player.addEventListener("onprogress", (e) => {
        const currentProgress = e.data;
        const item = Spicetify.Player.data?.item;
        if (!item) return;

        if (item.uri === lastTrackUri && currentProgress < 1000 && lastProgress > 5000) {
            logCurrentTrack(item);
        }
        lastProgress = currentProgress;
    });

    mount(); 
    window.refreshMyStats = render;
})();

(function volumePercentage() {
	const volumeBarSelectors = [
		".main-nowPlayingBar-volumeBar .progress-bar",
		".main-nowPlayingBar-volumeBar .x-progressBar-progressBarBg",
	]
	const volumeSliderSelectors = [
		".main-nowPlayingBar-volumeBar .progress-bar__slider",
	]

	const getFirstElement = (selectors) => {
    	for (const selector of selectors) {
        	const element = document.querySelector(selector);
        	if (element) return element;
    	}
    	return null;
	};

	const volumeBar = getFirstElement(volumeBarSelectors);
	const volumeSlider = getFirstElement(volumeSliderSelectors);

	if (!(volumeBar && volumeSlider && Spicetify.Platform.PlaybackAPI && Spicetify.Tippy && Spicetify.TippyProps)) {
		setTimeout(volumePercentage, 10);
		return;
	}

	const tippyInstance = Spicetify.Tippy(volumeBar, {
		...Spicetify.TippyProps,
		hideOnClick: false,
		interactive: true,
		allowHTML: true,
		interactiveBorder: 20,
		onMount(instance) {
			Spicetify.TippyProps.onMount(instance);
			updatePercentage();
		}
	});

	const updatePercentage = () => {
		const currVolume = Math.round(Spicetify.Platform.PlaybackAPI._volume * 100);
		tippyInstance.setContent(
			currVolume === -100
				? ``
				: `
				<div class="text">
					<input id="volumeInput" type="text" maxLength="3" value="${currVolume}">
					<style>
						.volume-bar__slider-container:focus-within { position: revert !important; }
						div.text { display: flex; align-items: center; }
						div.text:after { content: '%'; font-variant: unicase;}
						div.text input { min-width: 1ch; max-width: 3ch; padding: 0; font-size: 1em; text-align: center; border: 0; background: none; color: var(--spice-text); z-index: 1; outline: none !important; height: 1em; }
						div.text input::-webkit-outer-spin-button, div.text input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
					</style>
				</div>
				<div class="main-popper-arrow" style="bottom: -4px; position: absolute; left: calc(50% - 4px); background-color: var(--spice-card); width: 8px; height: 8px; transform: rotate(45deg); z-index: 0;"></div>
				`
		);
		adjustWidth(document.querySelector("#volumeInput"));
	};

	document.addEventListener("change", async e => {
		if (e.target && e.target.id === "volumeInput") {
			e.target.value = Math.min(100, Math.max(0, e.target.value));
			Spicetify.Platform.PlaybackAPI.setVolume(Number(e.target.value) / 100);
			adjustWidth(e.target);
		}
	});

	document.addEventListener("keydown", e => {
		if (e.target && e.target.id === "volumeInput" && e.key.length == 1 && isNaN(Number(e.key))) {
			e.preventDefault();
		}
	});

	document.addEventListener("input", e => {
		if (e.target && e.target.id === "volumeInput") {
			adjustWidth(e.target);
		}
	});

	volumeSlider.addEventListener(
		"mousedown",
		event => {
			tippyInstance.setProps({ trigger: "mousedown" });

			const onMouseUp = event => {
				tippyInstance.setProps({ trigger: "mouseenter focus" });
				if (event.srcElement !== volumeSlider) tippyInstance.hide();
				document.removeEventListener("mouseup", onMouseUp);
			};

			document.addEventListener("mouseup", onMouseUp);
		},
		{ capture: true }
	);

	let prevVolume = Spicetify.Platform.PlaybackAPI._volume;
	let hideTimeout;
	let isDragging = false;

	tippyInstance.popper.addEventListener("mouseenter", () => {
		clearTimeout(hideTimeout);
	});

	volumeBar.addEventListener("mouseenter", () => {
		clearTimeout(hideTimeout);
		isDragging = true;
	});

	volumeBar.addEventListener("mouseleave", event => {
		if (!event.buttons) {
			isDragging = false;
		}
	});

	Spicetify.Platform.PlaybackAPI._events.addListener("volume", e => {
		updatePercentage();

		if ((!tippyInstance.state.isVisible || hideTimeout) && !isDragging && e.data.volume !== prevVolume) {
			clearTimeout(hideTimeout);

			tippyInstance.show();
			hideTimeout = setTimeout(() => {
				tippyInstance.hide();
			}, 1000);
		}

		prevVolume = e.data.volume;
	});

	function adjustWidth(input) {
		if (!input) return;
		input.style.width = `${input.value.length}ch`;
		tippyInstance.popperInstance.update();
	}
})();

