var FORCE_HIDE_CSS='.Titlebar,.Titlebar *{pointer-events:none!important}.Titlebar button,.main-topBar-button:not(.cleanify-win-controls button),button[data-testid="topbar-close"],button[data-testid="topbar-minimize"],button[data-testid="topbar-maximize"]{display:none!important;visibility:hidden!important;pointer-events:none!important;opacity:0!important;width:0!important;height:0!important;padding:0!important;margin:0!important;overflow:hidden!important;position:absolute!important;top:-9999px!important}.body-drag-top{height:8px!important;top:0!important;left:0!important;right:0!important;position:absolute!important;-webkit-app-region:drag!important;pointer-events:auto!important}';
