// Bulletproof: route any pointer/click landing on a custom button's rect to that button,
// even if a native window control, drag region or overlay sits on top of it.
function btnAtPoint(x,y){
try{
var c=document.querySelector('.cleanify-win-controls');
if(!c||!c.isConnected)return null;
var btns=c.querySelectorAll('button');
for(var i=0;i<btns.length;i++){
var r=btns[i].getBoundingClientRect();
if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)return btns[i];
}
}catch(e){}
return null;
}
["pointerdown","mousedown","pointerup","mouseup","click"].forEach(function(evtName){
document.addEventListener(evtName,function(e){
var btn=btnAtPoint(e.clientX,e.clientY);
if(!btn)return;
if(!document.hasFocus()){try{window.focus();}catch(fe){}}
if(e.target===btn||(e.target&&btn.contains(e.target)))return;
e.stopImmediatePropagation();
e.preventDefault();
if(evtName==="click")btn.click();
},true);
});

var fullscreenGuard=setInterval(function(){
if(!document.fullscreenElement&&!document.webkitFullscreenElement&&!document.mozFullScreenElement&&!document.msFullscreenElement){
forceHideNativeButtons();
}
},500);

